function keDesimal(biner) {
  let hasil = 0;
  for (const bit of biner) {
    hasil = hasil * 2 + (bit === "1" ? 1 : 0);
  }
  return hasil;
}

function keBiner(n) {
  if (n === 0) return "0";
  let hasil = "";
  while (n > 0) {
    hasil = (n % 2) + hasil;
    n = Math.floor(n / 2);
  }
  return hasil;
}

