function urutanSelesai(proses, jatah) {
  const selesai = [];
  const antrean = proses.map(([nama, waktu]) => [nama, waktu]);
  while (antrean.length > 0) {
    const [nama, sisa] = antrean.shift();
    if (sisa <= jatah) selesai.push(nama);
    else antrean.push([nama, sisa - jatah]);
  }
  return selesai;
}

