function ukuranGiB(gb) {
  return Math.round((gb * 1e9) / 1024 ** 3 * 100) / 100;
}

function teksKeBiner(teks) {
  return [...teks].map((h) => h.charCodeAt(0).toString(2).padStart(8, "0"));
}

function muatFile(ukuranGB, sistemBerkas) {
  if (sistemBerkas === "FAT32") return ukuranGB <= 4;
  if (["exFAT", "NTFS", "ext4", "APFS"].includes(sistemBerkas)) return true;
  return null;
}

const LANGKAH = {
  "tidak-menyala": ["kabel daya", "PSU", "tombol power", "RAM"],
  "lambat": ["Task Manager", "startup app", "sisa disk", "RAM", "malware"],
  "layar-biru": ["catat kode error", "driver", "uji RAM", "uji disk"],
  "tidak-ada-internet": ["kabel/Wi-Fi", "ipconfig", "ping", "restart router"],
};

function langkahAwal(gejala) {
  return LANGKAH[gejala] ? [...LANGKAH[gejala]] : ["identifikasi gejala"];
}

function diagnosa(gejala, ukuranFileGB, sistemBerkas) {
  return { langkah: langkahAwal(gejala), fileMuat: muatFile(ukuranFileGB, sistemBerkas) };
}
